const err = $input.first().json;
return [{
  json: {
    workflow: err.workflow?.name || 'Loadsmart GTM Engine',
    node: err.execution?.lastNodeExecuted || 'Unknown Node',
    message: err.execution?.error?.message || 'Unspecified execution failure',
    execution_url: err.execution?.url || '',
    timestamp: new Date().toISOString()
  }
}];
